mapper.select:
SELECT g.id, g.school_id, s.school_name, g.grade_code, g.school_stage, g.grade_name, g.director_user_id, u.teacher_name AS directorName, g.remark, g.sort_no, g.create_time, g.update_time FROM t_educl_grade g LEFT JOIN t_school_manage s ON s.id = g.school_id LEFT JOIN t_as_teacher u ON u.id = g.director_user_id
g.is_valid = 1
AND g.school_id = #{query.schoolId}
AND g.grade_name LIKE concat('%', #{query.gradeName}, '%')
AND g.school_stage = #{query.schoolStage}
AND g.director_user_id = #{query.directorUserId}
AND g.create_time BETWEEN #{query.createTimeStart} AND #{query.createTimeEnd}
ORDER BY g.create_time DESC
